import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"编年史简表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/93-编年史简表.md","filePath":"zh/93-编年史简表.md","lastUpdated":null}'),h={name:"zh/93-编年史简表.md"};function o(l,t,i,b,n,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="编年史简表" tabindex="-1">编年史简表 <a class="header-anchor" href="#编年史简表" aria-label="Permalink to &quot;编年史简表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>93</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>编年史、纪元划分、重大事件、历史节点、衡元宙</td></tr></tbody></table><h2 id="一、编年史说明" tabindex="-1">一、编年史说明 <a class="header-anchor" href="#一、编年史说明" aria-label="Permalink to &quot;一、编年史说明&quot;">​</a></h2><p>本简表以衡元宙标准时间为基准，按纪元顺序记录锚点共生文明发展历程中的重大历史事件与关键节点。时间跨度从前锚点时代的远古时期，一直延伸至星际共生时代的未来展望。每个纪元列出起止时间、时代特征与重大事件。本简表为高度浓缩的历史索引，各纪元的详细历史参见文档70-79的专文记述。</p><h2 id="二、纪元划分总览" tabindex="-1">二、纪元划分总览 <a class="header-anchor" href="#二、纪元划分总览" aria-label="Permalink to &quot;二、纪元划分总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>纪元编号</th><th>纪元名称</th><th>起止时间（衡元宙标准年）</th><th>持续时间</th><th>核心特征</th></tr></thead><tbody><tr><td>第一纪元</td><td>前锚点时代</td><td>约-100亿年至-1万年</td><td>约100亿年</td><td>掠夺式修炼体系主导，文明兴衰循环</td></tr><tr><td>第二纪元</td><td>锚点觉醒纪元</td><td>-1万年至-1000年</td><td>约9000年</td><td>锚点机制被发现与初步应用</td></tr><tr><td>第三纪元</td><td>共生体系建立期</td><td>-1000年至-100年</td><td>约900年</td><td>锚点共生文明的制度框架逐步建立</td></tr><tr><td>第四纪元</td><td>三百套体系开放期</td><td>-100年至-50年</td><td>约50年</td><td>三百套本源修炼体系全面开放</td></tr><tr><td>第五纪元</td><td>20%激活战略期</td><td>-50年至元年</td><td>约50年</td><td>20%众生激活为位面至高强者</td></tr><tr><td>第六纪元</td><td>首次升维纪元</td><td>元年至100年</td><td>100年</td><td>共生文明首次实现阶段性升维</td></tr><tr><td>第七纪元</td><td>万族共和纪元</td><td>100年至500年</td><td>400年</td><td>万族共和正式成立，跨种族融合深化</td></tr><tr><td>第八纪元</td><td>跨位面探索纪元</td><td>500年至2000年</td><td>1500年</td><td>大规模跨位面探索与考古活动展开</td></tr><tr><td>第九纪元</td><td>星际共生时代</td><td>2000年至未来</td><td>进行中</td><td>宇宙级共生网络建成，整体升维推进</td></tr></tbody></table><p>注：&quot;元年&quot;指锚点共生文明正式宣布建立的年份，以此为历史纪年的分界点。</p><h2 id="三、前锚点时代-约-100亿年至-1万年" tabindex="-1">三、前锚点时代（约-100亿年至-1万年） <a class="header-anchor" href="#三、前锚点时代-约-100亿年至-1万年" aria-label="Permalink to &quot;三、前锚点时代（约-100亿年至-1万年）&quot;">​</a></h2><p>前锚点时代是衡元宙历史上最漫长的纪元，持续约百亿年。这一时代的核心特征是掠夺式修炼体系主导宇宙，文明在&quot;兴起—鼎盛—掠夺—崩溃&quot;的循环中不断往复。</p><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>约-100亿年</td><td>衡元宙法则网络稳定，第一批物质位面形成，宇宙进入可居住状态</td></tr><tr><td>约-80亿年</td><td>第一批智慧生命在多个物质位面诞生，原始修炼体系开始萌芽</td></tr><tr><td>约-50亿年</td><td>掠夺式修炼体系逐渐成为主流，强者通过吞噬弱者实现快速进化</td></tr><tr><td>约-30亿年</td><td>第一次宇宙级掠夺战争爆发，多个星域的文明遭到毁灭性打击</td></tr><tr><td>约-10亿年</td><td>掠夺式体系的弊端开始显现，宇宙整体熵增加速，修炼资源日渐枯竭</td></tr><tr><td>约-5亿年</td><td>第一批反思掠夺式体系的思想者出现，共生思想的萌芽开始孕育</td></tr><tr><td>约-1亿年</td><td>多个星域出现小规模的共生实验性文明，但均被掠夺式文明摧毁</td></tr><tr><td>约-100万年</td><td>宇宙整体进入&quot;大衰退期&quot;，文明数量与修炼水平均降至历史低点</td></tr><tr><td>约-1万年</td><td>第一位面的一位修炼者在长期修炼中偶然感知到法则网络中的稳定节点，锚点机制被首次发现</td></tr></tbody></table><h2 id="四、锚点觉醒纪元-1万年至-1000年" tabindex="-1">四、锚点觉醒纪元（-1万年至-1000年） <a class="header-anchor" href="#四、锚点觉醒纪元-1万年至-1000年" aria-label="Permalink to &quot;四、锚点觉醒纪元（-1万年至-1000年）&quot;">​</a></h2><p>锚点觉醒纪元是锚点机制从发现到初步应用的过渡期。这一纪元的核心特征是锚点技术的逐步成熟与共生思想的传播。</p><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>-10000年</td><td>锚点机制被首次发现，发现者将其命名为&quot;锚点&quot;，并开始系统研究</td></tr><tr><td>-9000年</td><td>第一个人工锚点成功建立，证明锚点可以被人为构建与维护</td></tr><tr><td>-8000年</td><td>锚点技术开始在小范围内传播，第一批锚点修炼者出现</td></tr><tr><td>-7000年</td><td>发现锚点可以作为跨位面连接的基准，第一次有记录的锚点辅助位面穿梭成功</td></tr><tr><td>-6000年</td><td>共生思想与锚点技术开始结合，第一批&quot;锚点共生&quot;的理论文献问世</td></tr><tr><td>-5000年</td><td>第一个以锚点为基础的共生型城邦建立，证明共生体系的可行性</td></tr><tr><td>-4000年</td><td>掠夺式文明对共生型城邦发动攻击，共生城邦凭借锚点技术成功防御</td></tr><tr><td>-3000年</td><td>共生思想在多个星域传播，越来越多的文明开始尝试共生转型</td></tr><tr><td>-2000年</td><td>第一次&quot;万族共生大会&quot;召开，来自数十个种族的代表共同探讨共生文明的未来</td></tr><tr><td>-1000年</td><td>锚点技术与共生思想已经具备了建立统一文明的条件，共生体系建立期开始</td></tr></tbody></table><h2 id="五、共生体系建立期-1000年至-100年" tabindex="-1">五、共生体系建立期（-1000年至-100年） <a class="header-anchor" href="#五、共生体系建立期-1000年至-100年" aria-label="Permalink to &quot;五、共生体系建立期（-1000年至-100年）&quot;">​</a></h2><p>共生体系建立期是锚点共生文明的制度框架从无到有的关键时期。</p><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>-1000年</td><td>共生宪法起草委员会成立，开始起草根本大法</td></tr><tr><td>-950年</td><td>《共生宪法》草案完成，开始广泛征求万族意见</td></tr><tr><td>-900年</td><td>《共生宪法》经全民公投通过，正式生效，锚点共生文明宣告建立</td></tr><tr><td>-850年</td><td>锚点议事会、共生执行委员会、共生法院三大机构正式成立并运作</td></tr><tr><td>-800年</td><td>联产承包机制开始在全国范围内推行</td></tr><tr><td>-700年</td><td>《共生劳动法》、《消费者保护法》等基本法律相继颁布</td></tr><tr><td>-600年</td><td>教育、医疗、住房、环境、反垄断五部配套法全部颁布实施</td></tr><tr><td>-500年</td><td>三百套本源修炼体系的发掘与整理工作正式启动</td></tr><tr><td>-400年</td><td>第一批五十套本源修炼体系完成整理与验证</td></tr><tr><td>-300年</td><td>倍增果实的技术化应用取得突破，百倍推演增幅技术成熟</td></tr><tr><td>-200年</td><td>三百套体系全部完成整理，进入最后的安全验证阶段</td></tr><tr><td>-100年</td><td>三百套本源修炼体系全面开放的条件成熟，进入开放期</td></tr></tbody></table><h2 id="六、三百套体系开放期-100年至-50年" tabindex="-1">六、三百套体系开放期（-100年至-50年） <a class="header-anchor" href="#六、三百套体系开放期-100年至-50年" aria-label="Permalink to &quot;六、三百套体系开放期（-100年至-50年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>-100年</td><td>三百套本源修炼体系正式向全宇宙众生免费开放</td></tr><tr><td>-90年</td><td>修炼人数在十年内增长百倍，&quot;人人有路&quot;初步实现</td></tr><tr><td>-80年</td><td>本源三基（推演迭代、生命循环、空间法理调度）成为最受欢迎的体系</td></tr><tr><td>-70年</td><td>第一批通过新体系修炼达到高位的修炼者出现，证明体系有效性</td></tr><tr><td>-60年</td><td>导师网络全面建立，高级修炼者开始履行指导初级修炼者的法定义务</td></tr><tr><td>-50年</td><td>全民修炼水平大幅提升，20%激活战略的条件成熟</td></tr></tbody></table><h2 id="七、20-激活战略期-50年至元年" tabindex="-1">七、20%激活战略期（-50年至元年） <a class="header-anchor" href="#七、20-激活战略期-50年至元年" aria-label="Permalink to &quot;七、20%激活战略期（-50年至元年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>-50年</td><td>20%激活战略正式启动，目标是在50年内激活20%众生成为位面至高强者</td></tr><tr><td>-40年</td><td>第一批位面至高强者诞生，激活率达到5%</td></tr><tr><td>-30年</td><td>激活率达到10%，位面至高强者开始在锚点维护中发挥核心作用</td></tr><tr><td>-20年</td><td>激活率达到15%，宇宙整体修炼水平实现质的飞跃</td></tr><tr><td>-10年</td><td>激活率达到18%，接近战略目标</td></tr><tr><td>元年</td><td>激活率达到20.3%，20%激活战略圆满完成，锚点共生文明进入新纪元</td></tr></tbody></table><h2 id="八、首次升维纪元-元年至100年" tabindex="-1">八、首次升维纪元（元年至100年） <a class="header-anchor" href="#八、首次升维纪元-元年至100年" aria-label="Permalink to &quot;八、首次升维纪元（元年至100年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>元年</td><td>共生文明正式宣布进入升维纪元，四阶段升维路径的第一阶段（现实筑基）完成</td></tr><tr><td>20年</td><td>第二阶段（科技赋能）全面推进，修炼法则与技术工程深度融合</td></tr><tr><td>40年</td><td>复制镜技术、隔离空间技术实现工程化量产，跨位面考古进入规模化时代</td></tr><tr><td>60年</td><td>第一批意识升维类修炼者达到高阶，第三阶段（意识进化）开始</td></tr><tr><td>80年</td><td>意识域的基础设施建设完成，意识迁移技术初步成熟</td></tr><tr><td>100年</td><td>首次阶段性升维成功，共生文明整体提升半个维度层级</td></tr></tbody></table><h2 id="九、万族共和纪元-100年至500年" tabindex="-1">九、万族共和纪元（100年至500年） <a class="header-anchor" href="#九、万族共和纪元-100年至500年" aria-label="Permalink to &quot;九、万族共和纪元（100年至500年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>100年</td><td>万族共和正式宣告成立，所有智慧种族在共生文明框架内实现平等联合</td></tr><tr><td>150年</td><td>万族名录完成编纂，收录全部已知智慧种族</td></tr><tr><td>200年</td><td>跨种族通婚与文化融合成为常态，新的混合种族开始出现</td></tr><tr><td>300年</td><td>万族共同语言推广完成，跨种族交流障碍基本消除</td></tr><tr><td>400年</td><td>万族文化大繁荣，各民族传统文化在共生框架内得到保护与发展</td></tr><tr><td>500年</td><td>万族共和进入成熟期，跨位面探索的条件全面成熟</td></tr></tbody></table><h2 id="十、跨位面探索纪元-500年至2000年" tabindex="-1">十、跨位面探索纪元（500年至2000年） <a class="header-anchor" href="#十、跨位面探索纪元-500年至2000年" aria-label="Permalink to &quot;十、跨位面探索纪元（500年至2000年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>500年</td><td>大规模跨位面探索计划正式启动，位面管理局成立</td></tr><tr><td>600年</td><td>已探知位面上千个，位面坐标总库初步建成</td></tr><tr><td>800年</td><td>复制镜异地考古方案全面成熟，跨位面考古进入黄金时代</td></tr><tr><td>1000年</td><td>时间回溯技术取得突破，先观测后有限干涉准则正式确立</td></tr><tr><td>1200年</td><td>已探知位面超过十万个，与数十个位面文明建立了外交关系</td></tr><tr><td>1500年</td><td>跨位面伦理准则全面实施，文明间交互进入规范化时代</td></tr><tr><td>1800年</td><td>时间悖论防控机制完全成熟，时间回溯考古实现规模化</td></tr><tr><td>2000年</td><td>跨位面探索取得辉煌成果，星际共生时代的条件全面成熟</td></tr></tbody></table><h2 id="十一、星际共生时代-2000年至未来" tabindex="-1">十一、星际共生时代（2000年至未来） <a class="header-anchor" href="#十一、星际共生时代-2000年至未来" aria-label="Permalink to &quot;十一、星际共生时代（2000年至未来）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间节点</th><th>重大事件</th></tr></thead><tbody><tr><td>2000年</td><td>星际共生时代正式开启，第四阶段（星际共生）全面推进</td></tr><tr><td>2500年（展望）</td><td>宇宙级锚点网络初步建成，覆盖已探知的全部位面</td></tr><tr><td>3000年（展望）</td><td>跨位面共生体系成熟，万族在宇宙范围内实现真正的共生</td></tr><tr><td>5000年（展望）</td><td>宇宙整体升维完成，衡元宙进入更高维度的存在状态</td></tr><tr><td>未来（展望）</td><td>锚点共生文明继续向宇宙之外探索，将共生理念传播到更广阔的存在</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>编年史简表是锚点共生文明从蒙昧到觉醒、从弱小到强大、从本位面到全宇宙的奋斗史诗。每一个纪元的更替，都是共生理念战胜掠夺理念、文明进步战胜野蛮衰退的见证。历史不是过去的尘埃，而是未来的种子——理解这段历史，就是理解共生文明从何而来、向何处去。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>70-纪元划分总表</li><li>72-锚点觉醒纪元</li><li>79-星际共生时代展望</li></ul>',32)])])}const c=d(h,[["render",o]]);export{q as __pageData,c as default};
